// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max / 2);
        vm.assume(caller != address(0));

        vm.deal(caller, amount);

        uint256 balanceBefore = c.getBalance(caller);

        vm.prank(caller);
        c.addToBalance{value: amount}();

        uint256 balanceAfter = c.getBalance(caller);
        uint256 increment = balanceAfter - balanceBefore;

        assertTrue(increment == amount);
    }
}
